        Arrays.sort(nums);
        int n = nums.length;

        int[][] C = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= Math.min(i, k); j++) {
                C[i][j] = (int)((C[i - 1][j - 1] + C[i - 1][j]) % MOD);
            }
        }

        int[][] prefC = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            int s = 0;
            for (int j = 0; j <= k; j++) {
                s = (int)((s + C[i][j]) % MOD);
                prefC[i][j] = s;
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            long maxWays = prefC[i][Math.min(k - 1, i)];
