    const prefC = Array.from({ length: n + 1 }, () => new BigInt64Array(k + 1));
    for (let i = 0; i <= n; i++) {
        let s = 0n;
        for (let j = 0; j <= k; j++) {
            s = (s + C[i][j]) % MOD;
            prefC[i][j] = s;
        }
